-- US admission requirements, wave 3 (schools 273 to 408 by program count), official pages, checked 13 Nov 2026. Needs step181.
update schools set admission_info = $q${"ug": "Send academic records, proof of English, a financial guarantee and the application fee. Documents must be originals or copies certified by the school or an EducationUSA advising center.", "english": "Proof of English is required. The pages read did not list accepted tests or minimum scores.", "how_to_apply": "Apply online. Every accepted international student gets a partial scholarship with the admission decision, and scholarships are the only aid for international applicants. No separate scholarship form.", "documents": "Academic records, proof of English, financial guarantee (bank statement showing at least $32,000 USD), certified copies.", "fees_link": "https://plattsburgh.edu/admissions/international/tuition.html", "sources": ["https://www.plattsburgh.edu/admissions/international/get-started/", "https://www.plattsburgh.edu/admissions/international/scholarships.html", "https://plattsburgh.edu/admissions/international/tuition.html"]}$q$::jsonb, admission_link = $q$https://plattsburgh.edu/admissions/international/tuition.html$q$, admission_checked = '2026-11-13' where id = 'd6053245-ca41-4447-918c-bc533ad92b5f' and country = 'United States';
update schools set admission_info = $q${"ug": "Online application, ACT of 16 or SAT of 790 (without writing), certified translated transcripts or an approved credential evaluation, Declaration of Financial Support (I-134) for one year, health form with measles, mumps and rubella proof, and tuberculosis chest X-ray proof.", "pg": "Online application, certified translated transcripts from all colleges sent directly to Graduate Studies, financial support declaration, immunization proof. Some departments ask for forms or three recommendation letters.", "english": "Undergraduate and graduate: TOEFL iBT 69 (undergraduate also lists CBT 194 or PBT 525), or IELTS 6.5 for graduate, or completing JSU's ESL program. Some applicants from English-speaking countries are exempt.", "how_to_apply": "Apply online through JSU Global. Admitted students receive an I-20 from JSU Global. The pages read listed no undergraduate international scholarships.", "deadlines": "Graduate: March 1 (Fall), October 1 (Spring), March 15 (Summer). Undergraduate deadlines not listed.", "application_fee": "$25 for graduate applicants. Undergraduate fee not listed.", "documents": "Certified transcripts, test scores, Declaration of Financial Support, immunization and TB records.", "fees_link": "https://www.jsums.edu/global/admissions/", "sources": ["https://www.jsums.edu/global/admissions/", "https://www.jsums.edu/global/?p=1713"]}$q$::jsonb, admission_link = $q$https://www.jsums.edu/global/admissions/$q$, admission_checked = '2026-11-13' where id = 'f24e8fdb-9411-48ab-86e3-d9c7babc3277' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply with the Common Application. Send notarized high school or college transcripts in English showing a 100-point or 4.0 GPA, or have them translated and evaluated (The Eval Company is recommended). Send a passport copy.", "english": "TOEFL 71 (online) or 530 (paper), IELTS 6.0 overall with no band below 6.0, or Duolingo 100. Waivers are considered case by case.", "how_to_apply": "All students are considered for GPA-based merit scholarships, renewable for up to eight semesters. After conditional acceptance, send the International Financial Certification Form and notarized bank statements.", "deadlines": "Fall: April 1. Spring: November 1.", "documents": "Notarized transcripts, passport copy, financial certification form, notarized bank statements.", "fees_link": "https://www.plymouth.edu/admissions/undergraduate/international-students", "sources": ["https://www.plymouth.edu/admissions/undergraduate/international-students"]}$q$::jsonb, admission_link = $q$https://www.plymouth.edu/admissions/undergraduate/international-students$q$, admission_checked = '2026-11-13' where id = 'c33559e1-8fa1-40d9-bafc-01bd46ca767d' and country = 'United States';
update schools set admission_info = $q${"ug": "Online international application, official high school transcripts with an English version, copy of diploma, official English test results, and a minimum GPA of 2.5 on a 4.0 scale. Transfer students need at least 2.25.", "pg": "Online international graduate application plus a departmental graduate application, official university transcripts, diploma copy, GRE if the program asks, and English results. Minimum GPA 3.0 on a 4.0 scale.", "english": "Undergraduate: TOEFL iBT 68, or IELTS 5.5 (5.0 in each skill). Graduate: TOEFL iBT 76 or IELTS 6.0, and some programs ask for more. Some English-speaking countries are exempt.", "how_to_apply": "Apply online. Admission is rolling and decisions usually take 2 to 3 weeks after all documents arrive. Official documents only; scans and photocopies are not accepted.", "deadlines": "No fixed deadline. Applications are accepted year round. Scholarship priority date is April 1.", "application_fee": "Not listed on the page read.", "documents": "Official transcripts, diploma copy, official English results.", "fees_link": "https://oip.sou.edu/?p=475", "sources": ["https://oip.sou.edu/?p=475", "https://oip.sou.edu/international-students/international-scholarships"]}$q$::jsonb, admission_link = $q$https://oip.sou.edu/?p=475$q$, admission_checked = '2026-11-13' where id = 'c6be4a47-cdaa-4dfa-a295-c39bea025159' and country = 'United States';
update schools set admission_info = $q${"ug": "Online application, unofficial secondary transcripts, and English results. Admission is based on core courses, GPA, class rank and test scores if available. ACT or SAT is not required. Minimum GPA for international first-year: same as domestic applicants. A WES evaluation may be requested.", "pg": "Apply through the graduate application. Official transcripts and English results are needed. The page read did not list graduate test rules, so check the program.", "english": "Full admission: TOEFL 4.5 (new scale), IELTS 6.5, PTE 58, Duolingo 115. A pathway option accepts IELTS 5.5 or Duolingo 105 and requires passing English 1110.", "how_to_apply": "Apply online as an F-1 or J-1 applicant. Rolling admission; send official sealed transcripts after admission. The Provost's International Merit Scholarship is awarded with the admission application.", "deadlines": "Recommended: April 1 for Fall, October 1 for Spring.", "application_fee": "Not listed on the page read.", "documents": "Transcripts, English results, optional personal statement, bank statement or sponsor proof after admission.", "fees_link": "https://futurestudents.mst.edu/admissions/international/freshmen/", "sources": ["https://futurestudents.mst.edu/admissions/international/freshmen/", "https://sfs.mst.edu/financialaid/typesofaid/scholarships/freshmen/automaticscholarships/merit-based/international/"]}$q$::jsonb, admission_link = $q$https://futurestudents.mst.edu/admissions/international/freshmen/$q$, admission_checked = '2026-11-13' where id = 'dd59db87-9530-403a-aaa6-e2a85ae9beba' and country = 'United States';
update schools set admission_info = $q${"ug": "Online application and fee, education records uploaded to My Warrior Life, and proof of English. Unofficial transcripts are accepted first; originals or certified copies are due before the first semester. Transfer students with 24 or more credits need a course-by-course evaluation.", "pg": "Apply to Graduate Studies and the program through GradCAS or AthleticTrainingCAS. Open to Athletic Training, Clinical Mental Health Counseling, Human Services Professional, Performance Analytics in Sport Science and School Counseling.", "english": "Undergraduate: TOEFL iBT 68, IELTS 5.5, PTE 47, Duolingo 5 or SAT 1060. Graduate: TOEFL iBT 80, IELTS 6.5, PTE 58. May be waived in some cases.", "how_to_apply": "Apply online. International students must buy the Minnesota State health plan.", "deadlines": "Undergraduate Fall: May 1 (Aug 10 if already in a US school). Spring: September 1 (Dec 1). Graduate: March 1.", "application_fee": "$20 undergraduate, plus a $100 processing fee for first-year applicants. Graduate fee not listed.", "documents": "Transcripts, credential evaluation (ECE, WES or similar), official English scores, health insurance.", "fees_link": "https://www.winona.edu/admissions/apply/international/", "sources": ["https://www.winona.edu/admissions/apply/international/", "https://www.winona.edu/international-services/scholarships.asp"]}$q$::jsonb, admission_link = $q$https://www.winona.edu/admissions/apply/international/$q$, admission_checked = '2026-11-13' where id = 'e6d81a3c-fbf4-4790-96f1-dc307590c39e' and country = 'United States';
update schools set admission_info = $q${"ug": "Complete the international online application and upload financial support documents, a signed Financial Disclaimer Form, transcripts, English score report from the last two years, and a passport copy.", "pg": "Offered in Accountancy (MAcc), MBA, Clinical Psychology, Social Work and Law (LL.M. and J.D.). Needs original transcripts, a course-by-course evaluation (ECE or WES) for non-US degrees, financial documents and English scores. Minimums vary by program.", "english": "Accepts Duolingo, IELTS, TOEFL iBT, Oxford ELLT or PTE from the last two years. Minimum scores are set by program and not listed on the page read.", "how_to_apply": "Apply online. Merit scholarships are automatic with admission. A $2,000 one-time administrative fee applies for first-time students.", "deadlines": "Spring: November 15. Summer: March 15. Fall: June 15.", "application_fee": "$70 application and processing fee.", "documents": "Financial documents, disclaimer form, transcripts, English scores, passport copy.", "fees_link": "https://www.washburn.edu/academics/international-programs/international-students", "sources": ["https://www.washburn.edu/academics/international-programs/international-students", "https://pubweb2-prod.washburn.edu/academics/international-programs/international-students/scholarships.html"]}$q$::jsonb, admission_link = $q$https://www.washburn.edu/academics/international-programs/international-students$q$, admission_checked = '2026-11-13' where id = '2b051796-b338-43cd-8bf8-77108407faaf' and country = 'United States';
update schools set admission_info = $q${"ug": "Graduation from secondary school with a B average or higher, following country-specific preparation rules. Music applicants must audition. Newly arrived students take English and math placement tests.", "english": "TOEFL iBT 71 minimum. Other ways to show English and conditional admission may be available.", "how_to_apply": "Apply through IU South Bend Office of International Student Services. The page read gave no deadlines, fee or full document list.", "fees_link": "https://admissions.iusb.edu/oiss/admissions/requirements/", "sources": ["https://admissions.iusb.edu/oiss/admissions/requirements/", "https://admissions.iusb.edu/oiss/admissions/explore/paying.html"]}$q$::jsonb, admission_link = $q$https://admissions.iusb.edu/oiss/admissions/requirements/$q$, admission_checked = '2026-11-13' where id = '5ad7c96f-b99f-42ea-a038-000ee48a755c' and country = 'United States';
update schools set admission_info = $q${"ug": "Application, official transcripts for grades 10 to 12 with diploma, original bank statement from the last 6 months, sponsor letter if the account is not yours, and a passport copy.", "pg": "Application, official undergraduate transcripts and diploma, financial documents, a recommendation letter, possibly a NACES credential evaluation, and GRE or GMAT only if the program requires it.", "english": "Undergraduate: TOEFL 3.5 (old scale 61), IELTS 5.5, Duolingo 95, PTE 46. Graduate: TOEFL 4.0 (old scale 70), IELTS 6.0, Duolingo 105, PTE 54. Some English-speaking countries are exempt.", "how_to_apply": "Apply through TROY and send documents as PDFs for first review. Scholarships are applied for through Academic Works.", "documents": "Transcripts, financial statement, sponsor letter, passport, English scores.", "fees_link": "https://troy.edu/international/study-troy/scholarships-more.html", "sources": ["https://www.troy.edu/applications-admissions/admissions-process-requirements/international-student/index.html", "https://troy.edu/international/study-troy/scholarships-more.html"]}$q$::jsonb, admission_link = $q$https://troy.edu/international/study-troy/scholarships-more.html$q$, admission_checked = '2026-11-13' where id = '7deffc5d-c079-40ed-a00f-f8161ff9057e' and country = 'United States';
update schools set admission_info = $q${"ug": "High school diploma with a 2.5 GPA on a 4.0 scale, or 2.5 for international college work. ACT and SAT are not required. Send official transcripts with English translation, English score, bank statement from the last 6 months and support forms.", "pg": "Minimum converted GPA 2.7 on a 4.0 scale. Official transcripts, English score, bank statement, financial support form and passport copy. Some programs, such as the MBA, add more.", "english": "Undergraduate: TOEFL iBT 68 (15 per section), IELTS 6.0, PTE 47, Duolingo 100. Some majors need higher scores and Nursing needs TOEFL iBT 79. Graduate minimums were not listed.", "how_to_apply": "Apply online. Conditional admission is possible for students who finish the Intensive English Program first.", "deadlines": "Fall: June 1. Spring: October 15.", "application_fee": "$60, non-refundable.", "documents": "Transcripts, diploma copy, English score, bank statement, financial support form, passport copy.", "fees_link": "https://pittstate.edu/admission/international-admission-information.html", "sources": ["https://pittstate.edu/admission/international-admission-information.html", "https://www.pittstate.edu/international/scholarships.html"]}$q$::jsonb, admission_link = $q$https://pittstate.edu/admission/international-admission-information.html$q$, admission_checked = '2026-11-13' where id = '7fedccf7-20e9-4f21-a0a0-624fa14881de' and country = 'United States';
update schools set admission_info = $q${"ug": "Open to first-year and transfer applicants who plan to apply for or hold an F-1 visa. Follow the undergraduate checklist on the NEIU site.", "pg": "Follow the graduate application checklist. Counseling and Social Work have their own deadlines.", "english": "Show a minimum score on an English exam, get a waiver for English-medium study, or enter through International Conditional Admission with the SAELL Intensive English Program. Minimum scores were not stated on the page read.", "how_to_apply": "Apply through NEIU international admissions. The page read listed no scholarships for international students.", "deadlines": "Undergraduate: Fall August 1, Spring December 1, Summer April 1. Graduate: Fall July 15, Spring November 1, Summer April 1.", "fees_link": "https://www.neiu.edu/admissions/international", "sources": ["https://www.neiu.edu/admissions/international"]}$q$::jsonb, admission_link = $q$https://www.neiu.edu/admissions/international$q$, admission_checked = '2026-11-13' where id = '809a1136-86ce-484c-8ce0-7775a9a8569d' and country = 'United States';
update schools set admission_info = $q${"ug": "Online international application, transcripts (unofficial first), English proof, passport copy, bank statement and UMSL Affidavit of Support. First-year students live in Oak Residence Hall.", "pg": "Application, unofficial transcripts from all colleges, and program materials such as recommendations, CV or GRE/GMAT. Graduate assistantships are limited and given by departments.", "english": "Undergraduate: TOEFL 61, IELTS 5.5, Duolingo 90, PTE 44. Graduate (recommended): TOEFL 79, IELTS 6.5, Duolingo 115, PTE 59.", "how_to_apply": "Apply online. Admitted F-1 students are automatically considered for International Merit Scholarships. Documents by email are not accepted.", "deadlines": "Priority: Fall July 15, Spring October 1. Some graduate programs are earlier.", "application_fee": "$40.", "documents": "Passport copy, bank statement under six months old, UMSL Affidavit of Support, transcripts, English scores.", "fees_link": "https://umsl.edu/global/admissions/undergrad.html", "sources": ["https://umsl.edu/global/admissions/undergrad.html", "https://umsl.edu/global/admissions/grad.html"]}$q$::jsonb, admission_link = $q$https://umsl.edu/global/admissions/undergrad.html$q$, admission_checked = '2026-11-13' where id = 'a2902ed4-3e10-4dbc-b2d7-78cbfb664ace' and country = 'United States';
