update schools set admission_info = $q${"ug": "Applicants on a non-immigrant visa can apply as international students and must study full time at the Portales campus. No score minimums are listed on the page checked.", "pg": "Needs an application, a signed financial declaration, and a transcript evaluation from an independent service for all college work.", "english": "Graduate: TOEFL iBT 79 or paper 550, or finishing the top level of an intensive English program. Undergraduate scores were not listed. A Pathway Program is offered for students who need English support.", "how_to_apply": "Undergraduate applicants apply online. The page mentions an International Scholarship but gives no details.", "deadlines": "Not listed.", "application_fee": "Undergraduate application is free. Graduate fee not listed.", "documents": "Graduate: application, financial declaration form, and an official transcript evaluation. Estimated yearly cost for the I-20 is $20,154.", "fees_link": "https://www.enmu.edu/admission/how-to-apply/international", "sources": ["https://www.enmu.edu/admission/how-to-apply/international", "https://enmu.edu/academics/colleges-departments/graduate-school/international-graduate-students"]}$q$::jsonb, admission_link = $q$https://www.enmu.edu/admission/how-to-apply/international$q$, admission_checked = '2026-11-13' where id = '85fd6e99-15df-4b2c-b11d-af30f36a2939' and country = 'United States';
update schools set admission_info = $q${"ug": "A course-by-course credential evaluation with GPA is needed. SAT or ACT is optional but helps for scholarships.", "pg": "Graduate assistantships exist (see scholarships). Graduate rules were not listed on the pages checked.", "english": "TOEFL iBT 68 (paper 520), IELTS 6.0, Duolingo 95, PTE 47, or SAT EBRW 480 (freshmen). Some countries are exempt.", "how_to_apply": "Apply with the international application and send all documents. Several scholarships are listed for international students.", "deadlines": "Not listed. Contact admissions@winthrop.edu.", "application_fee": "US $60, non-refundable.", "documents": "Official transcripts with certified translations, NACES credential evaluation, English proof, passport copy, and for visas a financial affidavit with bank letter.", "fees_link": "https://winthrop.edu/international/freshmen-students.aspx", "sources": ["https://winthrop.edu/international/freshmen-students.aspx", "https://winthrop.edu/international/scholarships.aspx"]}$q$::jsonb, admission_link = $q$https://winthrop.edu/international/freshmen-students.aspx$q$, admission_checked = '2026-11-13' where id = '5d936e47-d3db-4d8e-978f-9c5d4441f656' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen need two recommendation letters (one from a guidance counselor), a personal statement, evaluated transcripts, and immunization proof. SAT or ACT is optional.", "pg": "Needs an evaluated transcript showing a US degree equivalent, health and immunization forms, and a certified affidavit of support with a bank statement.", "english": "Official TOEFL, IELTS, Duolingo or Cambridge English scores for non-native speakers. The pages checked give no minimum scores.", "how_to_apply": "Apply online (VSU application is free) and mail the international supplement to the admissions office. The pages checked do not mention scholarships for international students.", "deadlines": "Graduate: complete the process before December 1 for spring or July 1 for fall.", "application_fee": "Undergraduate application is free. Graduate fee not listed.", "documents": "Application, International Applicant Supplement, official records, evaluated transcripts, English scores, two recommendation letters (freshmen), personal statement, and immunization proof.", "fees_link": "https://vsu.edu/admissions/apply/international-apply/", "sources": ["https://vsu.edu/admissions/apply/international-apply/", "https://www.vsu.edu/files/docs/admissions/international-students-graduate-admissions.pdf"]}$q$::jsonb, admission_link = $q$https://vsu.edu/admissions/apply/international-apply/$q$, admission_checked = '2026-11-13' where id = 'ea9d5932-ae8f-41f4-aa6b-ad7dda94e43d' and country = 'United States';
update schools set admission_info = $q${"ug": "The page checked covers money only. See the W&M international freshman admission pages for academic rules.", "pg": "Not checked.", "english": "Not listed on the page checked.", "how_to_apply": "W&M says it generally does not give scholarship or loan funds to undergraduate international students who are citizens of other countries, so families must fully pay. Estimated yearly cost is about $69,585.", "deadlines": "Not listed on the page checked.", "application_fee": "Not listed on the page checked.", "documents": "After admission and deposit, upload the passport page and proof of funding through iStart.", "fees_link": "https://wm.edu/admission/undergraduateadmission/how-to-apply/freshmanapplicants/internationalstudent/expensesaid", "sources": ["https://wm.edu/admission/undergraduateadmission/how-to-apply/freshmanapplicants/internationalstudent/expensesaid"]}$q$::jsonb, admission_link = $q$https://wm.edu/admission/undergraduateadmission/how-to-apply/freshmanapplicants/internationalstudent/expensesaid$q$, admission_checked = '2026-11-13' where id = 'f422c91c-49da-4e50-ac87-bc2850b77955' and country = 'United States';
update schools set admission_info = $q${"ug": "Empire State University cannot issue I-20s, so it does not offer F-1 study on a US campus. International students can take its 100 percent online programs from home.", "pg": "Same as undergraduate. Graduate pages were not checked in detail.", "english": "Required if English is not your first language. Minimum scores were not confirmed.", "how_to_apply": "Only online programs are open from abroad. Foreign credentials must be evaluated and the report sent directly to the university. The page does not mention scholarships.", "deadlines": "Not listed.", "application_fee": "Not listed.", "documents": "English proof and an official foreign credential evaluation sent directly to the university.", "fees_link": "https://sunyempire.edu/admissions/international-students", "sources": ["https://sunyempire.edu/admissions/international-students"]}$q$::jsonb, admission_link = $q$https://sunyempire.edu/admissions/international-students$q$, admission_checked = '2026-11-13' where id = 'f9cad0f7-4eec-401c-9f66-9fb5a30f14a0' and country = 'United States';
