update schools set admission_info = $q${"ug": "The page checked covers deadlines only. See the BSU undergraduate application page for academic rules.", "pg": "Not confirmed on the page checked.", "english": "Not listed on the pages checked.", "how_to_apply": "Apply at least six months before your start date. Over $3,000 in scholarships are available to international students through the Foundation Scholarship Application. International students cannot get federal or state aid or automatic New Freshman Scholarships.", "deadlines": "Fall: June 15 (outside US and Canada). Spring: October 15 (outside US and Canada). Rolling review. No summer start.", "application_fee": "Not listed on the page checked.", "documents": "Not listed on the page checked.", "fees_link": "https://www.bemidjistate.edu/admissions/international/admission-requirements/", "sources": ["https://www.bemidjistate.edu/admissions/international/admission-requirements/", "https://www.bemidjistate.edu/admissions/international/cost-scholarships/"]}$q$::jsonb, admission_link = $q$https://www.bemidjistate.edu/admissions/international/admission-requirements/$q$, admission_checked = '2026-11-13' where id = '8f85504d-ccfd-477b-8026-cd5260bb2da5' and country = 'United States';
