update schools set admission_info = $q${"ug": "Apply at applytexas.org. Freshmen send a high school transcript through SpanTran. TSIA2 is needed for placement, not admission.", "pg": "Needs a bachelor's equivalent, with undergraduate transcripts evaluated and the degree document translated.", "english": "TOEFL iBT 69 (paper 520), or iTEP 3.5. Waivers are possible with 6 credit hours of freshman English with a C or better.", "how_to_apply": "Apply online. International students cannot get federal or state grants but can apply for university and department scholarships, which are not guaranteed. A university scholarship of $1,000 or more can qualify a student for Texas resident tuition. Graduate students may apply for assistantships.", "deadlines": "Complete all steps by the deadline for your term. Dates not listed.", "application_fee": "$75, paid by card.", "documents": "Application, I-134 affidavit or bank statement (about $35,000 per year), transcripts through SpanTran, and a physician letter on health.", "fees_link": "https://www.sulross.edu/international-studies", "sources": ["https://www.sulross.edu/international-studies"]}$q$::jsonb, admission_link = $q$https://www.sulross.edu/international-studies$q$, admission_checked = '2026-11-13' where id = '4a88e60c-30b6-4390-9adc-3d506f580f7e' and country = 'United States';
