update schools set admission_info = $q${"ug": "Non-native speakers submit TOEFL or IELTS. Freshmen take a math placement test after arrival. A professional evaluation of all non-US transcripts is needed.", "pg": "Needs English scores and a graduate test (GRE, GMAT or MAT).", "english": "TOEFL iBT 69 or IELTS 6.0. Some students are exempt with 30 US college credits including English 1101 and 1102 with a C or better.", "how_to_apply": "Apply online. F-1 students cannot get federal or state aid but may apply for a limited number of service scholarships through the Center for Global Engagement.", "deadlines": "Summer: May 1. Fall: June 1. Spring: November 1.", "application_fee": "The page says a fee applies but gives no amount.", "documents": "Application, financial guarantee form with bank letter, transcript evaluation, test scores, and immunization certificate.", "fees_link": "https://www.columbusstate.edu/admissions/international/faq.php", "sources": ["https://www.columbusstate.edu/admissions/international/faq.php"]}$q$::jsonb, admission_link = $q$https://www.columbusstate.edu/admissions/international/faq.php$q$, admission_checked = '2026-11-13' where id = 'e3d3184d-ceea-4ec8-8f42-db43d9e86f14' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year applicants should have a high school average of 85 percent or higher by US standards.", "pg": "MS programs need a bachelor's degree and a 3.0 GPA (or 60 percent). GRE is optional. Some programs have extra subject rules.", "english": "Undergraduate: TOEFL 4 (new 0 to 6 scale), IELTS 6.0, PTE 53, Duolingo 105, iTEP 4.4. Graduate (Utica): IELTS 6.5, others as above.", "how_to_apply": "Apply through the international admissions pages. A separate merit scholarship page exists but was not read.", "deadlines": "Graduate: fall July 1, spring November 1. Undergraduate dates not listed on the page checked.", "application_fee": "Not listed on the pages checked.", "documents": "English or professionally translated records, with evaluation by a NACES member.", "fees_link": "https://sunypoly.edu/admissions/international-admissions/international-undergraduate-admissions/admission-requirements-first-year-freshman", "sources": ["https://sunypoly.edu/admissions/international-admissions/international-undergraduate-admissions/admission-requirements-first-year-freshman", "https://sunypoly.edu/admissions/international-admissions/international-graduate-admissions/international-admissions-graduate-admission-requirements"]}$q$::jsonb, admission_link = $q$https://sunypoly.edu/admissions/international-admissions/international-undergraduate-admissions/admission-requirements-first-year-freshman$q$, admission_checked = '2026-11-13' where id = '7d3cac48-542d-464b-b7e6-3edaff32e2e4' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year students need evaluated records (WES or ECE) and one entrance exam score.", "pg": "Graduate students must show financial proof, immunizations and TB screening. English minimums were not listed on the graduate page.", "english": "One test required: TOEFL iBT 71 (before Jan. 21, 2026), IELTS 6.0, Duolingo 105, PTE 50, SAT 920, or ACT 17. Exemptions apply for some US study.", "how_to_apply": "Apply online. The pages checked do not describe scholarships. International students cannot get US federal or state need-based aid.", "deadlines": "Fall: June 15 (outside US) or July 15 (inside US). Spring: October 15 or November 15.", "application_fee": "US $35.", "documents": "Academic records with WES or ECE evaluation, entrance exam score, I-20 application and financial certification, and a passport copy.", "fees_link": "https://minotstateu.edu/enroll/international/admissions-reqs.shtml", "sources": ["https://minotstateu.edu/enroll/international/admissions-reqs.shtml", "https://catalog.minotstateu.edu/graduate/admission-requirements/international-students/"]}$q$::jsonb, admission_link = $q$https://minotstateu.edu/enroll/international/admissions-reqs.shtml$q$, admission_checked = '2026-11-13' where id = 'c7ad1903-afaf-4869-b304-e256c79df273' and country = 'United States';
update schools set admission_info = $q${"ug": "Must be 16 or older and a high school graduate. A NACES evaluation of the high school record is needed. Transfers from US schools need a 2.0 GPA.", "pg": "Needs a NACES course-by-course evaluation, immunization form, recommendation form and supplemental form. Online-only and part-time programs are not open to international applicants.", "english": "Bachelor's: TOEFL iBT 4.0 (79 if taken before 2026), IELTS 6.5, PTE 58. Graduate: TOEFL iBT 79, IELTS 6.5.", "how_to_apply": "Apply through GAFutures. After admission you get information on the International Student Scholarship.", "deadlines": "Not listed on the pages checked.", "application_fee": "US $40, non-refundable.", "documents": "Application, evaluated transcripts, English scores, and proof of funds (about $43,000 for a bachelor's).", "fees_link": "https://ung.edu/undergraduate-admissions/international-student.php", "sources": ["https://ung.edu/undergraduate-admissions/international-student.php", "https://ung.edu/graduate-admissions/apply-now-international.php"]}$q$::jsonb, admission_link = $q$https://ung.edu/undergraduate-admissions/international-student.php$q$, admission_checked = '2026-11-13' where id = 'd6c186d4-0439-4a1e-823a-e6538d8071dd' and country = 'United States';
update schools set admission_info = $q${"ug": "Needs a 2.7 GPA, or ACT 20, or SAT 1030. High school records must be evaluated course by course with GPA.", "pg": "Not confirmed on the page checked.", "english": "TOEFL iBT 3.5 (paper 500), IELTS 5.5, PTE 44, iTEP 3.5. Some lower scores can be paired with an approved ESL program.", "how_to_apply": "Apply online. The page does not describe scholarships for international freshmen.", "deadlines": "Fall: June 1. Spring: November 1.", "application_fee": "US $30, non-refundable.", "documents": "Evaluated transcripts and diploma, affidavit of financial support, bank statement within 6 months, passport copy, and the Statement of Understanding.", "fees_link": "https://www.se.edu/international-student/international-undergraduate-students-freshmen/", "sources": ["https://www.se.edu/international-student/international-undergraduate-students-freshmen/"]}$q$::jsonb, admission_link = $q$https://www.se.edu/international-student/international-undergraduate-students-freshmen/$q$, admission_checked = '2026-11-13' where id = 'd7e1b51b-bb74-4df9-9e47-c5288b9d10d3' and country = 'United States';
