update schools set admission_info = $q${"ug": "Freshmen need transcripts for the final three years of secondary school with a 2.50 GPA equivalent. ACT or SAT is for placement only. Transfers need a 2.0 GPA.", "pg": "Needs certified English transcripts. The graduate program is fully online. No conditional admission for international applicants.", "english": "Undergraduate: IELTS 5, Duolingo 90, PTE 44, TOEFL iBT 61. Graduate: IELTS 6.0, Duolingo 100, PTE 53, TOEFL iBT 80. HSU code 6272.", "how_to_apply": "Apply online. The pages checked do not mention scholarships. Limited graduate assistantships exist.", "deadlines": "Undergraduate: fall May 31, spring October 31. Graduate: fall June 30, spring November 30.", "application_fee": "Undergraduate $30. Graduate $75.", "documents": "Application, official transcripts in English, passport copy, vaccination records, and an affidavit of support ($19,620 undergraduate, $15,924 graduate).", "fees_link": "https://hsu.edu/academics/international-programs/international-undergraduate-admissions/", "sources": ["https://hsu.edu/academics/international-programs/international-undergraduate-admissions/", "https://hsu.edu/academics/international-programs/international-graduate-admissions/"]}$q$::jsonb, admission_link = $q$https://hsu.edu/academics/international-programs/international-undergraduate-admissions/$q$, admission_checked = '2026-11-13' where id = '27eb7fc9-b18a-4078-acf2-7f9523deda5d' and country = 'United States';
update schools set admission_info = $q${"ug": "Needs high school transcripts and national exam results. The US equivalent minimum GPA is 2.5.", "pg": "The pages checked do not list graduate rules. Contact cie@smsu.edu.", "english": "TOEFL iBT 61, IELTS 5.5, Duolingo 95, PTE 47, MET 64, ACT 21, SAT EBRW 540, Cambridge B2. Some English-speaking countries are waived.", "how_to_apply": "Apply online, get the I-20, and attend the mandatory orientation. The pages checked do not mention scholarships.", "deadlines": "Fall: June 1. Spring: November 1.", "application_fee": "$100 from abroad, or $50 if already in the US on a student visa.", "documents": "Admission, bank statements under 3 months old, sponsor form if needed, and a colour passport photo page copy.", "fees_link": "https://catalog.smsu.edu/admission/international-student/", "sources": ["https://catalog.smsu.edu/admission/international-student/"]}$q$::jsonb, admission_link = $q$https://catalog.smsu.edu/admission/international-student/$q$, admission_checked = '2026-11-13' where id = '6217c87b-7b67-449d-8804-6d424b56be4e' and country = 'United States';
