update schools set admission_info = $q${"ug": "Send official transcripts and records, including your diploma and any national graduation test results.", "english": "You must show proof of English proficiency. The page does not list minimum scores; it links to an English Proficiency Requirements PDF.", "how_to_apply": "Pay the application fee, upload your passport page, send English proof and official transcripts. A signed Certificate of Financial Responsibility and bank statements are needed for the I-20. The page does not list international scholarships, but applying by the priority date gives early scholarship consideration.", "deadlines": "Fall 2027: applications open August 23 and the priority deadline is June 1. Spring: priority deadline October 1.", "application_fee": "$50 USD, non-refundable.", "documents": "Passport ID page, official transcripts, diploma, national exam results, English proof, signed financial responsibility form, bank statements.", "fees_link": "https://www.lcsc.edu/international/admissions/first-year-international-applicants", "sources": ["https://www.lcsc.edu/international/admissions/first-year-international-applicants"]}$q$::jsonb, admission_link = $q$https://www.lcsc.edu/international/admissions/first-year-international-applicants$q$, admission_checked = '2026-11-13' where id = 'f0a431bf-11f0-49bd-a4f4-0eb5deb8fab0' and country = 'United States';
update schools set admission_info = $q${"ug": "Official high school transcripts translated into English (for example by WES). Foreign college coursework needs a WES evaluation. Final high school transcripts are sent after acceptance.", "pg": "The Citadel has a separate Graduate College international page; graduate details were not confirmed here.", "english": "Required unless English is the only official language of your country. Minimums: TOEFL iBT 69, IELTS 6.0 (no part below 5.5), Duolingo 95, PTE 48. Scores must be under 2 years old.", "how_to_apply": "Apply as a non-citizen on a student visa. After acceptance pay the $300 enrollment deposit, get your I-20 and apply for the F-1 visa. The checklist does not mention scholarships.", "deadlines": "Not listed on the international checklist.", "application_fee": "Application fee not listed on the checklist. After acceptance: $300 enrollment deposit and $350 I-901 fee.", "documents": "Passport copy matching the I-20, translated transcripts, WES evaluation for foreign college work, International Supplement, bank statement under 6 months old.", "fees_link": "https://www.citadel.edu/corps/wp-content/uploads/sites/27/Intl-Student-Checklist-Undergrad-2026-v3.pdf", "sources": ["https://www.citadel.edu/corps/wp-content/uploads/sites/27/Intl-Student-Checklist-Undergrad-2026-v3.pdf"]}$q$::jsonb, admission_link = $q$https://www.citadel.edu/corps/wp-content/uploads/sites/27/Intl-Student-Checklist-Undergrad-2026-v3.pdf$q$, admission_checked = '2026-11-13' where id = '08cc8d57-04d6-4ea6-b626-cf3e99f0d7e1' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply with the SUNY Application or Common App. Send transcripts and exam scores in English, an essay, at least one recommendation letter for freshmen, and the International Student Financial Statement.", "pg": "Your degree should equal a U.S. bachelor's degree (usually 4 years of college study). A NACES credential evaluation can prove this. Apply through the Graduate Application portal.", "english": "Undergraduate: TOEFL iBT 79, IELTS 6.0, Duolingo 100, SAT 1000 or ACT 21 also accepted. Graduate: TOEFL iBT 79, IELTS 6.0, PTE 51, Duolingo 100 (institution code 2545). Conditional admission is possible through an English program.", "how_to_apply": "Apply online, send documents, then show a financial guarantee for one year dated within 9 months of your start. New students are automatically considered for merit scholarships.", "deadlines": "Common App fall 2026 deadline was July 28, 2026. After that use the SUNY Application before the semester starts. No graduate deadline listed on this page.", "application_fee": "$50 USD for undergraduate.", "documents": "Transcripts, passport photo page, essay, recommendation letter, financial statement, address verification form, audition for Crane School of Music.", "fees_link": "https://www.potsdam.edu/admissions/apply/international", "sources": ["https://www.potsdam.edu/admissions/apply/international", "https://www.potsdam.edu/admissions/financial/types/scholarships/internationalscholarship"]}$q$::jsonb, admission_link = $q$https://www.potsdam.edu/admissions/apply/international$q$, admission_checked = '2026-11-13' where id = '31a4a016-85a6-4d7b-8340-39f536463619' and country = 'United States';
update schools set admission_info = $q${"ug": "Official high school or college transcripts. Foreign transcripts need a course-by-course evaluation (IEE, WES, Spantran or similar). WAEC applicants must give scratch card details. SAT or ACT is strongly recommended.", "pg": "Foreign degree must equal a U.S. bachelor's degree, shown by a course-by-course evaluation with GPA. Unconditional admission needs GPA 2.5 or higher (3.0 for MBA, 2.7 for MAT). Conditional admission needs 2.2 or higher.", "english": "Undergraduate: TOEFL iBT 61, IELTS 5.5, PTE 43, Duolingo 90, SAT Verbal 410 or ACT English 19. Graduate: TOEFL iBT 79, IELTS 6.0, PTE 51, Duolingo 100.", "how_to_apply": "Apply online, pay the fee, send evaluated transcripts and financial proof. SAU says test scores affect scholarship eligibility, but amounts and criteria were not listed.", "deadlines": "Graduate: Fall 2026 deadline July 16, 2026; Spring 2027 deadline December 4, 2026. Undergraduate deadlines not listed.", "application_fee": "Undergraduate $90. Graduate $90, or $230 if SAU also does the foreign transcript evaluation.", "documents": "Transcripts or evaluations sent officially, passport copy, bank statement, SAU Affidavit of Support showing at least $17,375 (graduate).", "fees_link": "https://www.saumag.edu/international/admission/graduate/", "sources": ["https://www.saumag.edu/international/admission/graduate/", "https://www.saumag.edu/international/admissions/undergraduate/undergrad-admissions-criteria/"]}$q$::jsonb, admission_link = $q$https://www.saumag.edu/international/admission/graduate/$q$, admission_checked = '2026-11-13' where id = '332029d4-3d62-4701-9af5-f3362629f49f' and country = 'United States';
update schools set admission_info = $q${"ug": "Transcripts must be evaluated course by course with GPA by a NACES member or Atlas. SAT or ACT is needed if your calculated GPA is between 2.5 and 2.8. Proof of funding is required.", "pg": "Same transcript evaluation rule. Apply through the Broncoville portal. Some programs need a statement of purpose and recommendation letters.", "english": "Undergraduate: TOEFL iBT 61 or paper 500, IELTS 6, Duolingo 94. Graduate: TOEFL or IELTS valid within 2 years; no minimum listed.", "how_to_apply": "Apply through the Broncoville portal or CFNC, send evaluated transcripts, English scores and a financial statement. The page lists no specific scholarships. Call the International Programs office on (910) 672-2198 to confirm the funding amount, since the page gives conflicting periods.", "deadlines": "Not listed on this page.", "application_fee": "Not listed on this page.", "documents": "Evaluated transcripts, English scores, financial statement.", "fees_link": "https://www.uncfsu.edu/admission-and-aid/international", "sources": ["https://www.uncfsu.edu/admission-and-aid/international"]}$q$::jsonb, admission_link = $q$https://www.uncfsu.edu/admission-and-aid/international$q$, admission_checked = '2026-11-13' where id = 'b8372d85-7bb6-4e73-8d8c-903124e0b416' and country = 'United States';
update schools set admission_info = $q${"ug": "Online application, official transcripts evaluated by an approved NACES agency, English proof, passport copy and financial statement. First-year students must send final high school transcripts before the end of their first semester.", "pg": "Same application steps. MBA and nursing have higher English scores. No other graduate rules listed on this page.", "english": "Most programs: TOEFL paper 500, IELTS 5.5, Duolingo 95 (undergraduate only). MBA and nursing: TOEFL paper 550, IELTS 6.0. Newer TOEFL iBT scores are on a 1 to 6 scale; confirm the cutoff with admissions.", "how_to_apply": "Apply online and send documents to info@csupueblo.edu. You cannot be admitted without a financial statement covering the full cost of attendance. The page does not describe scholarships.", "deadlines": "Not listed on this page.", "application_fee": "$30 undergraduate, $35 graduate, non-refundable.", "documents": "Transcripts with evaluation, English proof, passport, bank certificate dated within 6 months, or a loan agreement or scholarship letter.", "fees_link": "https://catalog.csupueblo.edu/admission-requirements/international-students/", "sources": ["https://catalog.csupueblo.edu/admission-requirements/international-students/"]}$q$::jsonb, admission_link = $q$https://catalog.csupueblo.edu/admission-requirements/international-students/$q$, admission_checked = '2026-11-13' where id = 'cb0f1010-e291-4301-bf82-4ba30dcbdd1d' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year applicants send official transcripts from all schools (grades 9 to 11 if still in school). Transfer applicants send all college transcripts. A NACES course-by-course evaluation may be required.", "pg": "Not all graduate programs accept international applicants. Contact the graduate advisor of your program.", "english": "Proof such as TOEFL or IELTS is required. Minimum scores were not listed on this page.", "how_to_apply": "Apply online as an international applicant. After admission and final transcripts, show enough funds to get the I-20. First-year students are admitted for autumn and winter only. The page does not cover scholarships.", "deadlines": "Specific dates not listed on this page.", "application_fee": "US $75, non-refundable.", "documents": "Official transcripts with English translation, test scores sent by the testing agency, proof of funds after admission.", "fees_link": "https://www.tacoma.uw.edu/node/2212", "sources": ["https://www.tacoma.uw.edu/node/2212"]}$q$::jsonb, admission_link = $q$https://www.tacoma.uw.edu/node/2212$q$, admission_checked = '2026-11-13' where id = 'd18c458f-58d3-4ed9-b31d-2797495817fe' and country = 'United States';
update schools set admission_info = $q${"ug": "Finish a secondary program like a U.S. high school. Send official transcripts, Leaving School Certificates or affidavits of support, TOEFL or WAEC scores, and SAT or ACT scores, all translated and certified.", "english": "TOEFL 400 to 449: earn a C or better in Freshman Composition (ESL). TOEFL 450 to 499: earn a C or better in English 111 (ESL).", "how_to_apply": "Apply at least 90 days before registration with the $30 fee as a money order or cashier's check. Affidavits of support must be original, notarized and cover your first year. F-1 students take at least 15 hours. Scholarships were not covered on this page.", "deadlines": "Completed applications must arrive at least 90 days before registration.", "application_fee": "$30, by money order or cashier's check.", "documents": "Transcripts, certificates, affidavit of support, TOEFL or WAEC scores, SAT or ACT scores, certified translations.", "fees_link": "https://subr.smartcatalogiq.com/en/2024-2026/undergraduate-catalog/office-of-enrollment-management/undergraduate-admissions/admissions-for-freshmen-international-students", "sources": ["https://subr.smartcatalogiq.com/en/2024-2026/undergraduate-catalog/office-of-enrollment-management/undergraduate-admissions/admissions-for-freshmen-international-students"]}$q$::jsonb, admission_link = $q$https://subr.smartcatalogiq.com/en/2024-2026/undergraduate-catalog/office-of-enrollment-management/undergraduate-admissions/admissions-for-freshmen-international-students$q$, admission_checked = '2026-11-13' where id = 'dd514ed1-0c17-4b77-8475-63b9d07429c1' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply on the First Year or Transfer page, submit the International Supplemental Form, official transcripts with a course-by-course evaluation (WES, ECE or a NACES member), and one recommendation letter.", "pg": "Apply through the Graduate page. Same evaluation rule. Other graduate rules were not on this page.", "english": "Required if English is not your first language. TOEFL (code 2878): iBT 80 before 2026 or 4.5 after, IELTS 6.5, Duolingo 105. Applicants below the minimum are not eligible.", "how_to_apply": "Apply, complete the International Supplemental Form, send transcripts and English scores, then request an I-20. Scholarship details were not on this page; contact the international advisor.", "deadlines": "Not listed on this page.", "application_fee": "Not listed on this page.", "documents": "Evaluated transcripts, English scores sent by the testing service, recommendation letter, passport page, visa copy if you have one.", "fees_link": "https://www.purchase.edu/admissions/international-students/", "sources": ["https://www.purchase.edu/admissions/international-students/"]}$q$::jsonb, admission_link = $q$https://www.purchase.edu/admissions/international-students/$q$, admission_checked = '2026-11-13' where id = '07dcdf9d-66b9-41ca-a9c6-4f42f391ce08' and country = 'United States';
update schools set admission_info = $q${"how_to_apply": "Undergraduate international applicants pay a $75 application fee online. Requirements, deadlines and scholarships were not on this page; email intlstu@ecok.edu or call (580) 559-5669.", "application_fee": "$75 for undergraduate international applicants, paid online.", "fees_link": "https://www.ecok.edu/International", "sources": ["https://www.ecok.edu/International"]}$q$::jsonb, admission_link = $q$https://www.ecok.edu/International$q$, admission_checked = '2026-11-13' where id = '1d01e990-495d-4008-8a65-589df69ff894' and country = 'United States';
update schools set admission_info = $q${"ug": "Send all academic records in English and your own language, evaluated by a NACES-approved group. Applicants under 21 need SAT or ACT. Two recommendation letters are required.", "english": "Non-native speakers must show English proof. The page does not give accepted tests or scores.", "how_to_apply": "Apply at least 4 months before your semester with a $25 fee, then send financial documents. Scholarships were not covered on this page.", "deadlines": "Apply at least 4 months before the semester. General priority dates are May 1 for fall and October 1 for spring.", "application_fee": "$25, non-refundable, in U.S. funds.", "documents": "Evaluated records, SAT or ACT if under 21, two recommendations, notarized affidavit of support, student certification form, bank statements in English and U.S. dollars.", "fees_link": "https://catalog.nsu.edu/undergraduate/admissions/", "sources": ["https://catalog.nsu.edu/undergraduate/admissions/"]}$q$::jsonb, admission_link = $q$https://catalog.nsu.edu/undergraduate/admissions/$q$, admission_checked = '2026-11-13' where id = '2481e47b-de8f-4efc-9118-4ac99fc6042c' and country = 'United States';
update schools set admission_info = $q${"how_to_apply": "International undergraduates who qualify for admission are automatically considered for tuition waiver awards, so no separate scholarship form is needed. Admission rules and fee are on the 'How to Apply as an International Student' page, which was not read.", "documents": "For the F-1 visa, show funds of at least $32,385 (standard), $26,485 (with the NTW Award) or $24,285 (with the NTW Scholar Award).", "fees_link": "https://uwsuper.edu/paying-for-college/international-students/", "sources": ["https://uwsuper.edu/paying-for-college/international-students/"]}$q$::jsonb, admission_link = $q$https://uwsuper.edu/paying-for-college/international-students/$q$, admission_checked = '2026-11-13' where id = '6718dab7-859c-43f4-9d7f-b78b3c74e089' and country = 'United States';
update schools set admission_info = $q${"ug": "Send official high school or college transcripts directly from the school, converted to U.S. standards by ECE, IERF or WES.", "pg": "Graduate students contact the Graduate Studies admissions office on (671) 735-2205.", "english": "TOEFL paper 500, iBT 61, or IELTS 5.5. Or finish the university's English Language Institute program.", "how_to_apply": "Apply online, send converted transcripts, English proof, immunization records and a Financial Support Form with a bank statement. Health insurance of at least $1,000 valid on Guam is required. No international scholarships were listed.", "deadlines": "Fall 2027 (Aug to Dec): March 15, 2027. Spring 2028 (Jan to May): September 3, 2027. Summer 2027: February 8, 2027.", "application_fee": "$77.", "documents": "Transcripts with credential conversion, release form, TOEFL or IELTS, immunization records, medical form, passport and visa copy if any, financial support form with bank statement.", "fees_link": "https://uog.edu/admissions/international-students.php", "sources": ["https://uog.edu/admissions/international-students.php"]}$q$::jsonb, admission_link = $q$https://uog.edu/admissions/international-students.php$q$, admission_checked = '2026-11-13' where id = '98848520-217f-4093-b585-eda4ba4e1c4b' and country = 'United States';
update schools set admission_info = $q${"ug": "High school transcript with at least a 2.5 GPA on a 4.0 scale, proof of graduation, and a bank letter. Non-English transcripts need evaluation (WES, ECE or SpanTran).", "pg": "Graduate rules were not listed. Fully online graduate programs do not qualify for student visas.", "english": "TOEFL iBT 61, Duolingo 95 or IELTS 5.5. Also accepted if English is an official language in your country or your high school taught in English.", "how_to_apply": "Apply online and pay the fee at the end. Send a bank letter with your application. Undergraduate international applicants get the Ambassador International Scholarship automatically.", "deadlines": "No general deadline listed. Housing application runs October 1 to August 1.", "application_fee": "$130.", "documents": "Transcript, graduation proof, bank letter, passport valid 6 months past entry, I-20, DS-160, immunization records.", "fees_link": "https://directory.utm.edu/admissions-and-aid/international.php", "sources": ["https://directory.utm.edu/admissions-and-aid/international.php"]}$q$::jsonb, admission_link = $q$https://directory.utm.edu/admissions-and-aid/international.php$q$, admission_checked = '2026-11-13' where id = '9a52cef8-c92b-43c6-8e01-63ae2a1e820a' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year: secondary school graduate with GPA of at least 2.35 and college readiness in English and math (for example ACT English 18, Math 19). Transfers need a 2.0 GPA and English and math completed.", "pg": "Requirements vary. MBA needs a 2.75 GPA and GRE 286 or GMAT 400. Engineering needs a 3.00 GPA and GRE 300.", "english": "TOEFL iBT 79, IELTS 6.5, Duolingo 100 or PTE 50. International transfers need TOEFL 71 or IELTS 6.0.", "how_to_apply": "Apply by the deadline and send forms listed on the international admissions page. International scholarships exist for freshmen, transfers and graduate students.", "deadlines": "Fall: June 1. Spring: October 1.", "application_fee": "Not listed on this page.", "documents": "Forms on the McNeese international admissions page. Financial proof rules were not specified.", "fees_link": "https://www.mcneese.edu/admissions/international-requirements", "sources": ["https://www.mcneese.edu/admissions/international-requirements", "https://www.mcneese.edu/financial-aid/international-scholarships/"]}$q$::jsonb, admission_link = $q$https://www.mcneese.edu/admissions/international-requirements$q$, admission_checked = '2026-11-13' where id = 'a433c102-ddf9-460f-a4a7-85c6ce41980a' and country = 'United States';
update schools set admission_info = $q${"ug": "Final high school transcript evaluated by TEC (or NACES), SAT or ACT score, English score, bank statement and passport.", "pg": "Course-by-course evaluation from a NACES member for any college work outside the U.S. Graduate rules were not listed separately.", "english": "IELTS, TOEFL or Duolingo accepted. Minimum scores were not on this page.", "how_to_apply": "Submit the international application with the fee and the documents listed. You get an acceptance letter and a dean letter. Scholarships were not on this page.", "deadlines": "Not listed on this page.", "application_fee": "$50.", "documents": "Transcript evaluation, SAT or ACT, English score, bank statement showing $32,575, passport valid 6 months.", "fees_link": "https://www.shawnee.edu/admission/international/admission-process", "sources": ["https://www.shawnee.edu/admission/international/admission-process"]}$q$::jsonb, admission_link = $q$https://www.shawnee.edu/admission/international/admission-process$q$, admission_checked = '2026-11-13' where id = '081f9d21-8849-4aa1-b0a1-04b5ffca2e36' and country = 'United States';
update schools set admission_info = $q${"ug": "Official transcripts of completed and in-progress work with grading scale, sent directly from your school, with certified English translation if needed. Passport page copy.", "pg": "Apply for graduate status if you have or are about to finish a U.S. bachelor's equivalent. Official transcripts, passport copy and financial proof are needed.", "english": "Required if English is not your native language. TOEFL is preferred; minimum scores are on the English Proficiency Documentation page. Scores must come directly from ETS.", "how_to_apply": "Apply online, upload documents through your Atlas account and send originals to the International Student Services office. Financial proof must cover the first year and be under 12 months old. IU Kokomo lists several international scholarships.", "deadlines": "Not listed on this page.", "application_fee": "$65, non-refundable (undergraduate).", "documents": "Transcripts, passport copy, bank statement or scholarship letter, I-94 and visa stamp if in the U.S.", "fees_link": "https://kokomo.iu.edu/international-student-services/admissions/first-year-undergraduate.html", "sources": ["https://kokomo.iu.edu/international-student-services/admissions/first-year-undergraduate.html", "https://kokomo.iu.edu/international-student-services/admissions/graduate-students.html", "https://kokomo.iu.edu/international-student-services/admissions/international-student-scholarships.html"]}$q$::jsonb, admission_link = $q$https://kokomo.iu.edu/international-student-services/admissions/first-year-undergraduate.html$q$, admission_checked = '2026-11-13' where id = '127eca70-742e-4517-aef6-2f3d6469de99' and country = 'United States';
update schools set admission_info = $q${"ug": "SAT or ACT is required for freshmen. High school transcripts need a general evaluation with GPA from TEC, WES or ECE. University transcripts need a course-by-course evaluation.", "pg": "Course-by-course evaluation for each non-U.S. school. Only the MBA is listed as open to F-1 students.", "english": "TOEFL iBT 70 (paper 525). IELTS and Duolingo accepted but scores not listed. Waived for applicants from English-speaking countries with proof of English instruction.", "how_to_apply": "Apply, send evaluated transcripts, test scores, an affidavit of financial support and bank statements. Undergraduates are matched automatically to academic scholarships by GPA or test score. Graduate students can apply for assistantships and scholarships.", "deadlines": "Fall: application June 1, documents July 1. Spring: application October 15, documents November 15.", "application_fee": "Not listed. International students pay an extra $500 per semester.", "documents": "Evaluation, SAT or ACT, MMR vaccine proof, TB chest X-ray, affidavit of support, bank statement. Required yearly sponsorship amount is $23,500.", "fees_link": "https://www.deltastate.edu/admissions/international/", "sources": ["https://www.deltastate.edu/admissions/international/"]}$q$::jsonb, admission_link = $q$https://www.deltastate.edu/admissions/international/$q$, admission_checked = '2026-11-13' where id = '4e698ba1-9d82-4227-b084-7eeaa41e2c0a' and country = 'United States';
