update schools set admission_info = $q${"ug": "Online application, SAT or ACT, and transcripts evaluated by Lisano International, WES or a NACES member. Admission uses GPA with test score, for example GPA 2.5 to 2.99 with ACT 17 or SAT 820.", "pg": "Bachelor's degree with at least 2.5 GPA. Needs resume, transcripts, GRE or GMAT, three recommendations and a statement of purpose. Applied through GradCAS.", "english": "Regular admission: TOEFL iBT 70 or IELTS 5.5. Another section lists lower TOEFL minimums and Duolingo 100; confirm with admissions.", "how_to_apply": "Apply, pay the fee, and send the notarized Confidential Financial Support Affidavit. The I-20 is issued after all requirements are met. International students can get academic scholarships and assistantships but not federal or institutional financial aid.", "deadlines": "Undergraduate: fall June 1, spring November 1, summer April 1. Graduate priority: spring November 15, summer March 15, fall April 15.", "application_fee": "$30 (undergraduate). SEVIS fee about $350.", "documents": "Evaluated transcripts, test scores, notarized affidavit, health form with TB results, health insurance with repatriation cover.", "fees_link": "https://alasu.edu/admissions/international-students.php", "sources": ["https://alasu.edu/admissions/international-students.php"]}$q$::jsonb, admission_link = $q$https://alasu.edu/admissions/international-students.php$q$, admission_checked = '2026-11-13' where id = 'de77b8a7-4b89-4984-8849-fb044727ff02' and country = 'United States';
