update schools set admission_info = $q${"ug": "SAT 940 or higher (or ACT 18), a 2.0 GPA equivalent, and a NACES course-by-course foreign credential evaluation dated within one year.", "pg": "Degree equal to a U.S. bachelor's, undergraduate GPA of at least 2.6 (or 3.0 on the last 60 hours), and financial statement of at least $36,107 per year.", "english": "Undergraduate: TOEFL iBT 61, IELTS 5.0, Duolingo 85. Graduate: TOEFL iBT 79, IELTS 6.0, Duolingo 100, PTE 53. Graduate scores must be under 2 years old.", "how_to_apply": "Apply through ApplyTexas (undergraduate) or GradCAS (graduate). Show a bank statement in English dated within 6 months. No scholarships were listed.", "deadlines": "Undergraduate fall: June 25 (U.S.) or July 1 (abroad). Spring: December 2 or November 18 (abroad). Graduate: fall June 1, spring October 1, summer April 1.", "application_fee": "$50 undergraduate. $69 graduate.", "documents": "Credential evaluation, SAT or ACT, financial statement of at least $33,887 per year (undergraduate), immigration documents.", "fees_link": "https://catalog.tamusa.edu/undergraduate/student-enrollment/admissions/international/", "sources": ["https://catalog.tamusa.edu/undergraduate/student-enrollment/admissions/international/", "https://catalog.tamusa.edu/graduate/student-enrollment/admissions/international/"]}$q$::jsonb, admission_link = $q$https://catalog.tamusa.edu/undergraduate/student-enrollment/admissions/international/$q$, admission_checked = '2026-11-13' where id = '115b984b-2dba-4c8d-b36e-4343ac744bbf' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply as a freshman or transfer and mark student visa. Official transcripts from all schools and a NACES evaluation (WES, ECE or SpanTran).", "pg": "Requirements vary by department. Check the program finder.", "english": "Undergraduate: TOEFL iBT 73, IELTS 5.0, Duolingo 90 to 95. Graduate: TOEFL iBT 75, IELTS 5.5, Duolingo 100 to 105.", "how_to_apply": "Apply, then send the admission letter, passport page and proof of at least $30,000 in a bank statement under 6 months old to internationaloffice@bowiestate.edu. Scholarships were not on this page.", "deadlines": "Fall (outside the U.S.): apply by June 1, documents by June 30. Spring: November 1.", "application_fee": "Not listed on this page.", "documents": "Transcripts, evaluation, passport page, bank statement, sponsor letter if sponsored.", "fees_link": "https://bowiestate.edu/admissions-and-aid/international-admissions.php", "sources": ["https://bowiestate.edu/admissions-and-aid/international-admissions.php"]}$q$::jsonb, admission_link = $q$https://bowiestate.edu/admissions-and-aid/international-admissions.php$q$, admission_checked = '2026-11-13' where id = '2444b3e6-6ae0-45e9-b737-178d82671cd3' and country = 'United States';
update schools set admission_info = $q${"ug": "First-time freshmen need a 2.6 GPA, transfers 2.0. Send an official stamped transcript; foreign credit needs a WES or ECE evaluation.", "pg": "MBA and MSIG: program-specific requirements, and WES or ECE evaluation for foreign degrees.", "english": "TOEFL iBT 61, IELTS 5.5, Duolingo 90, PTE 44 (graduate also accepts these). May be waived for some West African students with a WAEC English score above C4.", "how_to_apply": "Apply, send transcripts, English proof, request an I-20 and show a bank statement for the one-year cost. BHSU offers several international scholarships.", "deadlines": "Fall: June 1. Spring: November 1.", "application_fee": "$25 undergraduate, $40 graduate.", "documents": "Transcript, passport page, I-20 request form, MMR proof, bank statement signed and stamped by the bank.", "fees_link": "https://www.bhsu.edu/international", "sources": ["https://www.bhsu.edu/international", "https://bhsu.edu/International/Future-International-Students/International-Undergraduate-Admissions/Apply-for-Scholarships"]}$q$::jsonb, admission_link = $q$https://www.bhsu.edu/international$q$, admission_checked = '2026-11-13' where id = '59771559-64fa-48a5-b12a-2c9115c42b00' and country = 'United States';
